[CmdletBinding()]
param([string]$Workspace,[string]$Head,[string]$Base,[string]$Path,[string]$OutputDirectory,[string]$AssemblyDirectory,[switch]$Stress)
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not $AssemblyDirectory){$AssemblyDirectory=Join-Path $PSScriptRoot 'bin-native'}
$refs=@('System.dll','System.Core.dll','System.Windows.Forms.dll','System.Drawing.dll','System.Web.Extensions.dll')
foreach($name in @('SolidWorks.Interop.sldworks.dll','SolidWorks.Interop.swpublished.dll','Gitpolar.SolidWorks.dll')){$file=Join-Path $AssemblyDirectory $name;[void][Reflection.Assembly]::LoadFrom($file);$refs+=$file}
Add-Type -ReferencedAssemblies $refs -TypeDefinition @'
using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;using Gitpolar.SolidWorks;using SolidWorks.Interop.sldworks;
public static class NativeEditorCapture {
 sealed class Host:Form {public Host(){Opacity=0;ShowInTaskbar=false;}protected override bool ShowWithoutActivation{get{return true;}}}
 static object Call(object instance,string name,params object[] args){return instance.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(instance,args);}
 static Dictionary<string,object> State(object form){return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>((string)Call(form,"StateJson"));}
 static async Task Wait(Form form){await Task.Delay(80);for(int i=0;i<1600;i++){var state=State(form);if(!(bool)state["loading"])return;await Task.Delay(25);}throw new Exception("Native window did not finish loading.");}
 public static object Run(object instance,string workspace,string head,string baseline,string path,string output,bool stress){Exception failure=null;var controller=new GitpolarPane((ISldWorks)instance);controller.Settings.Workspace=workspace;controller.Settings.Repository=new DirectoryInfo(workspace).Name;Dictionary<string,object> graphState=null,branchState=null;var assembly=typeof(GitpolarPane).Assembly;Directory.CreateDirectory(output);
 using(var host=new Host()){host.ClientSize=new Size(1470,920);host.Shown+=(sender,args)=>{controller.AttachDispatcher(host);controller.StartUi(async()=>{Form graph=null,branches=null;try{
 graph=(Form)Activator.CreateInstance(assembly.GetType("Gitpolar.SolidWorks.GraphForm"),BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{controller},null);graph.TopLevel=false;host.Controls.Add(graph);graph.Show();await Wait(graph);if(stress){string[] revisions=Git.Run(workspace,"rev-list","--all","--max-count=6").Split(new char[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);for(int round=0;round<3;round++)foreach(string revision in revisions){Call(graph,"SelectForAutomation",revision,baseline,path);await Task.Delay(10);}Call(graph,"SelectForAutomation",head,baseline,"missing-preview-file.SLDPRT");await Wait(graph);var missing=State(graph);if((bool)missing["beforePreview"]||(bool)missing["afterPreview"]||Convert.ToString(missing["status"]).Contains("就绪"))throw new Exception("Missing CAD was reported as successfully previewed.");}Call(graph,"SelectForAutomation",head,baseline,path);await Wait(graph);graphState=State(graph);Call(graph,"SaveScreenshot",System.IO.Path.Combine(output,"gitpolar-gitgraph-cad-compare.png"));if(!(bool)graphState["beforePreview"]||!(bool)graphState["afterPreview"])throw new Exception("Comparison images were not both produced: "+new JavaScriptSerializer().Serialize(graphState));graph.Hide();
 branches=(Form)Activator.CreateInstance(assembly.GetType("Gitpolar.SolidWorks.BranchManagerForm"),BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{controller,head},null);branches.TopLevel=false;host.Controls.Add(branches);branches.Show();await Wait(branches);Call(branches,"SaveScreenshot",System.IO.Path.Combine(output,"gitpolar-gitgraph-branches.png"));Call(branches,"ShowManualMerge");branches.PerformLayout();await Task.Delay(25);Call(branches,"SaveScreenshot",System.IO.Path.Combine(output,"gitpolar-gitgraph-manual-merge.png"));branchState=State(branches);
 }catch(Exception error){failure=error;}finally{if(graph!=null){graph.Close();graph.Dispose();}if(branches!=null){branches.Close();branches.Dispose();}controller.Stop();host.Close();}});};Application.Run(host);}if(failure!=null)throw failure;return new {ok=true,rapidSelectionChecked=stress,missingPreviewChecked=stress,graph=graphState,branches=branchState};}
}
'@
$sw=[Runtime.InteropServices.Marshal]::GetActiveObject('SldWorks.Application')
[NativeEditorCapture]::Run($sw,$Workspace,$Head,$Base,$Path,$OutputDirectory,[bool]$Stress)|ConvertTo-Json -Compress -Depth 12
